 public static void ModelTest(string manifest,string catalog,string output){Directory.CreateDirectory(output);var entries=NrModels.Parse(File.ReadAllText(manifest));Check(entries.Count==4&&entries.All(x=>x.Tag.StartsWith("dlssnr-")),"actual NR family filtering");Reject(()=>NrModels.Compatible(entries.First(x=>!x.Community),40),"original NR on RTX40");NrModels.Compatible(entries.First(x=>!x.Community),50);NrModels.Compatible(entries.First(x=>x.Community),40);foreach(string file in DlssLibraries.Names)Check(DllCatalog.Parse(File.ReadAllText(catalog),file).Count==10,"ten historical component versions");Core.Data=Path.Combine(output,"data");Directory.CreateDirectory(Core.Data);var g=new Game{Id="fixture",Name="NR fixture",Root=Path.Combine(output,Guid.NewGuid().ToString("N"))};Directory.CreateDirectory(g.Root);g.Exe=Path.Combine(g.Root,"game.exe");Pe(g.Exe,false);string source=Path.Combine(output,"nr-fixture.dll");Pe(source,false);DlssCore.Apply(g,NrModels.Prepare(g,source,entries[0]));Check(File.Exists(Path.Combine(g.Root,"nvngx_dlssnr.dll")),"NR install");DlssCore.Apply(g,NrModels.Restore(g));Check(!File.Exists(Path.Combine(g.Root,"nvngx_dlssnr.dll")),"NR removal");File.WriteAllText(Path.Combine(output,"model.txt"),"PASS: four actual NR repository variants filtered; RTX40 original rejection; GPU variant matching; ten historical SR/RR/FG versions; isolated model installation and restoration fixtures. Downloads of live NR models not exercised.");}
 public static void Catalog(string manifest,string archive,string output){Directory.CreateDirectory(output);string json=File.ReadAllText(manifest);foreach(string name in DlssLibraries.Names){var versions=DllCatalog.Parse(json,name);Check(versions.Count==10&&versions.Select(x=>x.Version).Distinct().Count()==10,"ten distinct component versions");Check(versions.All(x=>new Uri(x.Url).Host=="dlss-swapper-downloads.beeradmoore.com"),"catalog source");}var item=DllCatalog.Parse(json,"nvngx_dlssg.dll")[0];DllCatalog.Extract(item,archive,Path.Combine(output,item.File));item.ZipMd5=new string('0',32);Reject(()=>DllCatalog.Extract(item,archive,Path.Combine(output,"invalid.dll")),"tampered archive accepted");File.WriteAllText(Path.Combine(output,"catalog.txt"),"PASS: actual catalog contains ten distinct signed non-development versions per component; newest FG ZIP extracted and hash, NVIDIA signature, component and exact version verified; altered digest rejected.");}
