 static void ClickLabel(System.Windows.DependencyObject node,string label){var button=node as Button;if(button!=null&&Convert.ToString(button.Content)==label){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));return;}foreach(var child in LogicalTreeHelper.GetChildren(node).OfType<System.Windows.DependencyObject>())ClickLabel(child,label);}
 static void Render(Window w,string path){w.UpdateLayout();var bitmap=new System.Windows.Media.Imaging.RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,System.Windows.Media.PixelFormats.Pbgra32);bitmap.Render(w);var png=new System.Windows.Media.Imaging.PngBitmapEncoder();png.Frames.Add(System.Windows.Media.Imaging.BitmapFrame.Create(bitmap));using(var f=File.Create(path))png.Save(f);}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static void Reject(Action action,string why){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,why);}
